    /// <summary>
    /// The details of the Firewall Manager policy to be created. PolicyId -&gt; (string) The ID of the Firewall Manager policy. Constraints: o min: 36 o max: 36 o pattern: ^[a-z0-9A-Z-]{36}$ PolicyName -&gt; (string) [required] The name of the Firewall Manager policy. Constraints: o min: 1 o max: 128 o pattern: ^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$ PolicyUpdateToken -&gt; (string) A unique identifier for each update to the policy. When issuing a PutPolicy request, the PolicyUpdateToken in the request must match the PolicyUpdateToken of the current policy version. To get the PolicyUpdateToken of the current policy version, use a GetPolicy request. Constraints: o min: 1 o max: 1024 o pattern: ^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$ SecurityServicePolicyData -&gt; (structure) [required] Details about the security service that is being used to protect the resources. Type -&gt; (string) [required] The service that the policy is using to protect the re- sources. This specifies the type of policy that is created, either an WAF policy, a Shield Advanced policy, or a security group policy. For security group policies, Firewall Manager supports one security group for each common policy and for each content audit policy. This is an adjustable limit that you can increase by contacting Amazon Web Services Support. Possible values: o WAF o WAFV2 o SHIELD_ADVANCED o SECURITY_GROUPS_COMMON o SECURITY_GROUPS_CONTENT_AUDIT o SECURITY_GROUPS_USAGE_AUDIT o NETWORK_FIREWALL o DNS_FIREWALL o THIRD_PARTY_FIREWALL o IMPORT_NETWORK_FIREWALL o NETWORK_ACL_COMMON ManagedServiceData -&gt; (string) Details about the service that are specific to the service type, in JSON format. o Example: DNS_FIREWALL "{\"type\":\"DNS_FIREWALL\",\"pre- ProcessRuleGroups\":[{\"rule- GroupId\":\"rslvr-frg-1\",\"priority\":10}],\"postProcess- RuleGroups\":[{\"ruleGroupId\":\"rslvr-frg-2\",\"prior- ity\":9911}]}" NOTE: Valid values for preProcessRuleGroups are between 1 and 99. Valid values for postProcessRuleGroups are between 9901 and 10000. o Example: IMPORT_NETWORK_FIREWALL "{\"type\":\"IM- PORT_NETWORK_FIREWALL\",\"awsNetworkFirewallCon- fig\":{\"networkFirewallStatelessRuleGroupRefer- ences\":[{\"resourceARN\":\"arn:aws:network-fire- wall:us-west-2:000000000000:stateless-rule- group\/rg1\",\"priority\":1}],\"networkFirewallStatelessDe- faultActions\":[\"aws:drop\"],\"networkFirewallStateless- FragmentDefaultActions\":[\"aws:pass\"],\"networkFirewall- StatelessCustomActions\":[],\"networkFirewallStatefulRule- GroupReferences\":[{\"resourceARN\":\"arn:aws:network-fire- wall:us-west-2:aws-managed:stateful-rulegroup\/ThreatSigna- turesEmergingEventsStrictOrder\",\"priority\":8}],\"net- workFirewallStatefulEngineOptions\":{\"rule- Order\":\"STRICT_ORDER\"},\"networkFirewallStatefulDefault- Actions\":[\"aws:drop_strict\"]}}" "{\"type\":\"DNS_FIREWALL\",\"preProcessRule- Groups\":[{\"ruleGroupId\":\"rslvr-frg-1\",\"prior- ity\":10}],\"postProcessRuleGroups\":[{\"rule- GroupId\":\"rslvr-frg-2\",\"priority\":9911}]}" NOTE: Valid values for preProcessRuleGroups are between 1 and 99. Valid values for postProcessRuleGroups are between 9901 and 10000. o Example: NETWORK_FIREWALL - Centralized deployment model "{\"type\":\"NETWORK_FIREWALL\",\"awsNetworkFirewallCon- fig\":{\"networkFirewallStatelessRuleGroupRefer- ences\":[{\"resourceARN\":\"arn:aws:network-fire- wall:us-east-1:123456789011:stateless-rule- group/test\",\"priority\":1}],\"networkFirewallStatelessDe- faultActions\":[\"aws:forward_to_sfe\",\"customAction- Name\"],\"networkFirewallStatelessFragmentDefaultAc- tions\":[\"aws:forward_to_sfe\",\"customAction- Name\"],\"networkFirewallStatelessCustomActions\":[{\"ac- tionName\":\"customActionName\",\"actionDefini- tion\":{\"publishMetricAction\":{\"dimen- sions\":[{\"value\":\"metricdimensionvalue\"}]}}}],\"net- workFirewallStatefulRuleGroupReferences\":[{\"re- sourceARN\":\"arn:aws:network-fire- wall:us-east-1:123456789011:stateful-rule- group/test\"}],\"networkFirewallLoggingConfigura- tion\":{\"logDestinationConfigs\":[{\"logDestination- Type\":\"S3\",\"logType\":\"ALERT\",\"logDestina- tion\":{\"bucketName\":\"s3-bucket-name\"}},{\"logDestina- tionType\":\"S3\",\"logType\":\"FLOW\",\"logDestina- tion\":{\"bucketName\":\"s3-bucket-name\"}}],\"overrideEx- istingConfig\":true}},\"firewallDeploymentModel\":{\"cen- tralizedFirewallDeploymentModel\":{\"centralizedFirewal- lOrchestrationConfig\":{\"inspectionVpcIds\":[{\"resour- ceId\":\"vpc-1234\",\"accoun- tId\":\"123456789011\"}],\"firewallCreationConfig\":{\"end- pointLocation\":{\"availabilityZoneConfigList\":[{\"avail- abilityZoneId\":null,\"availabilityZone- Name\":\"us-east-1a\",\"al- lowedIPV4CidrList\":[\"10.0.0.0/28\"]}]}},\"al- lowedIPV4CidrList\":[]}}}}" To use the centralized de- ployment model, you must set PolicyOption to CENTRALIZED . o Example: NETWORK_FIREWALL - Distributed deployment model with automatic Availability Zone configuration "{\"type\":\"NETWORK_FIREWALL\",\"networkFirewallStateless- RuleGroupReferences\":[{\"resourceARN\":\"arn:aws:net- work-firewall:us-east-1:123456789011:stateless-rule- group/test\",\"priority\":1}],\"networkFirewallStatelessDe- faultActions\":[\"aws:forward_to_sfe\",\"customAction- Name\"],\"networkFirewallStatelessFragmentDefaultAc- tions\":[\"aws:forward_to_sfe\",\"customAction- Name\"],\"networkFirewallStatelessCustomActions\":[{\"ac- tionName\":\"customActionName\",\"actionDefini- tion\":{\"publishMetricAction\":{\"dimen- sions\":[{\"value\":\"metricdimensionvalue\"}]}}}],\"net- workFirewallStatefulRuleGroupReferences\":[{\"re- sourceARN\":\"arn:aws:network-fire- wall:us-east-1:123456789011:stateful-rule- group/test\"}],\"networkFirewallOrchestrationCon- fig\":{\"singleFirewallEndpointPerVPC\":false,\"al- lowedIPV4CidrList\":[\"10.0.0.0/28\",\"192.168.0.0/28\"],\"route- ManagementAction\":\"OFF\"},\"networkFirewallLoggingConfig- uration\":{\"logDestinationConfigs\":[{\"logDestination- Type\":\"S3\",\"logType\":\"ALERT\",\"logDestina- tion\":{\"bucketName\":\"s3-bucket-name\"}},{\"logDestina- tionType\":\"S3\",\"logType\":\"FLOW\",\"logDestina- tion\":{\"bucketName\":\"s3-bucket-name\"}}],\"overrideEx- istingConfig\":true}}" With automatic Availbility Zone configuration, Firewall Manager chooses which Availability Zones to create the endpoints in. To use the distributed deployment model, you must set PolicyOption to NULL . o Example: NETWORK_FIREWALL - Distributed deployment model with automatic Availability Zone configuration and route management "{\"type\":\"NETWORK_FIREWALL\",\"networkFire- wallStatelessRuleGroupReferences\":[{\"re- sourceARN\":\"arn:aws:network-fire- wall:us-east-1:123456789011:stateless-rule- group/test\",\"priority\":1}],\"networkFirewallStatelessDe- faultActions\":[\"aws:forward_to_sfe\",\"customAction- Name\"],\"networkFirewallStatelessFragmentDefaultAc- tions\":[\"aws:forward_to_sfe\",\"customAction- Name\"],\"networkFirewallStatelessCustomActions\":[{\"ac- tionName\":\"customActionName\",\"actionDefini- tion\":{\"publishMetricAction\":{\"dimen- sions\":[{\"value\":\"metricdimensionvalue\"}]}}}],\"net- workFirewallStatefulRuleGroupReferences\":[{\"re- sourceARN\":\"arn:aws:network-fire- wall:us-east-1:123456789011:stateful-rule- group/test\"}],\"networkFirewallOrchestrationCon- fig\":{\"singleFirewallEndpointPerVPC\":false,\"al- lowedIPV4CidrList\":[\"10.0.0.0/28\",\"192.168.0.0/28\"],\"route- ManagementAction\":\"MONITOR\",\"routeManagementTarget- Types\":[\"InternetGateway\"]},\"networkFirewallLoggingCon- figuration\":{\"logDestinationConfigs\":[{\"logDestination- Type\":\"S3\",\"logType\":\"ALERT\",\"logDestina- tion\":{\"bucketName\":\"s3-bucket-name\"}},{\"logDestina- tionType\":\"S3\",\"logType\": \"FLOW\",\"logDestina- tion\":{\"bucketName\":\"s3-bucket-name\"}}],\"overrideEx- istingConfig\":true}}" To use the distributed deployment model, you must set PolicyOption to NULL . o Example: NETWORK_FIREWALL - Distributed deployment model with custom Availability Zone configuration "{\"type\":\"NETWORK_FIREWALL\",\"networkFirewallStateless- RuleGroupReferences\":[{\"resourceARN\":\"arn:aws:net- work-firewall:us-east-1:123456789011:stateless-rule- group/test\",\"priority\":1}],\"networkFirewallStatelessDe- faultActions\":[\"aws:forward_to_sfe\",\"customAction- Name\"],\"networkFirewallStatelessFragmentDefaultAc- tions\":[\"aws:forward_to_sfe\",\"fragmentcustomaction- name\"],\"networkFirewallStatelessCustomActions\":[{\"ac- tionName\":\"customActionName\", \"actionDefini- tion\":{\"publishMetricAction\":{\"dimen- sions\":[{\"value\":\"metricdimensionvalue\"}]}}},{\"ac- tionName\":\"fragmentcustomactionname\",\"actionDefini- tion\":{\"publishMetricAction\":{\"dimen- sions\":[{\"value\":\"fragmentmetricdimensionva- lue\"}]}}}],\"networkFirewallStatefulRuleGroupRefer- ences\":[{\"resourceARN\":\"arn:aws:network-fire- wall:us-east-1:123456789011:stateful-rule- group/test\"}],\"networkFirewallOrchestrationCon- fig\":{\"firewallCreationConfig\":{ \"endpointLoca- tion\":{\"availabilityZoneConfigList\":[{\"availabilityZo- neName\":\"us-east-1a\",\"al- lowedIPV4CidrList\":[\"10.0.0.0/28\"]},{\"availabilityZone- Name\":\"us-east-1b\",\"allowedIPV4CidrList\":[ \"10.0.0.0/28\"]}]} },\"singleFirewallEndpointPer- VPC\":false,\"allowedIPV4CidrList\":null,\"routeManagemen- tAction\":\"OFF\",\"networkFirewallLoggingConfigura- tion\":{\"logDestinationConfigs\":[{\"logDestination- Type\":\"S3\",\"logType\":\"ALERT\",\"logDestina- tion\":{\"bucketName\":\"s3-bucket-name\"}},{\"logDestina- tionType\":\"S3\",\"logType\":\"FLOW\",\"logDestina- tion\":{\"bucketName\":\"s3-bucket-name\"}}],\"overrideEx- istingConfig\":boolean}}" With custom Availability Zone configuration, you define which specific Availability Zones to create endpoints in by configuring firewallCreationCon- fig . To configure the Availability Zones in firewallCre- ationConfig , specify either the availabilityZoneName or availabilityZoneId parameter, not both parameters. To use the distributed deployment model, you must set PolicyOption to NULL . o Example: NETWORK_FIREWALL - Distributed deployment model with custom Availability Zone configuration and route man- agement "{\"type\":\"NETWORK_FIREWALL\",\"networkFirewall- StatelessRuleGroupReferences\":[{\"re- sourceARN\":\"arn:aws:network-fire- wall:us-east-1:123456789011:stateless-rule- group/test\",\"priority\":1}],\"networkFirewallStatelessDe- faultActions\":[\"aws:forward_to_sfe\",\"customAction- Name\"],\"networkFirewallStatelessFragmentDefaultAc- tions\":[\"aws:forward_to_sfe\",\"fragmentcustomaction- name\"],\"networkFirewallStatelessCustomActions\":[{\"ac- tionName\":\"customActionName\",\"actionDefini- tion\":{\"publishMetricAction\":{\"dimen- sions\":[{\"value\":\"metricdimensionvalue\"}]}}},{\"ac- tionName\":\"fragmentcustomactionname\",\"actionDefini- tion\":{\"publishMetricAction\":{\"dimen- sions\":[{\"value\":\"fragmentmetricdimensionva- lue\"}]}}}],\"networkFirewallStatefulRuleGroupRefer- ences\":[{\"resourceARN\":\"arn:aws:network-fire- wall:us-east-1:123456789011:stateful-rule- group/test\"}],\"networkFirewallOrchestrationCon- fig\":{\"firewallCreationConfig\":{\"endpointLoca- tion\":{\"availabilityZoneConfigList\":[{\"availabilityZo- neName\":\"us-east-1a\",\"al- lowedIPV4CidrList\":[\"10.0.0.0/28\"]},{\"availabilityZone- Name\":\"us-east-1b\",\"al- lowedIPV4CidrList\":[\"10.0.0.0/28\"]}]}},\"singleFirewal- lEndpointPerVPC\":false,\"al- lowedIPV4CidrList\":null,\"routeManagementAction\":\"MONI- TOR\",\"routeManagementTargetTypes\":[\"InternetGate- way\"],\"routeManagementConfig\":{\"allowCrossAZTrafficIf- NoEndpoint\":true}},\"networkFirewallLoggingConfigura- tion\":{\"logDestinationConfigs\":[{\"logDestination- Type\":\"S3\",\"logType\":\"ALERT\",\"logDestina- tion\":{\"bucketName\":\"s3-bucket-name\"}},{\"logDestina- tionType\":\"S3\",\"logType\":\"FLOW\",\"logDestina- tion\":{\"bucketName\":\"s3-bucket-name\"}}],\"overrideEx- istingConfig\":boolean}}" To use the distributed deploy- ment model, you must set PolicyOption to NULL . o Example: SECURITY_GROUPS_COMMON "{\"type\":\"SECU- RITY_GROUPS_COMMON\",\"security- Groups\":[{\"id\":\"sg-03b1f67d69ed00197\"}],\"revertManu- alSecurityGroupChanges\":true,\"exclusiveResourceSecurity- GroupManagement\":true,\"applyToAllEC2InstanceE- NIs\":false,\"includeSharedVPC\":true,\"enableSecurity- GroupReferencesDistribution\":true}" o Example: SECURITY_GROUPS_COMMON - Security group tag dis- tribution ""{\"type\":\"SECURITY_GROUPS_COMMON\",\"secu- rityGroups\":[{\"id\":\"sg-000e55995d61a06bd\"}],\"revert- ManualSecurityGroupChanges\":true,\"exclusiveResourceSecu- rityGroupManagement\":false,\"applyToAllEC2InstanceE- NIs\":false,\"includeSharedVPC\":false,\"enableTagDistribu- tion\":true}"" Firewall Manager automatically distributes tags from the primary group to the security groups created by this policy. To use security group tag distribution, you must also set revertManualSecurityGroupChanges to true , otherwise Firewall Manager won't be able to create the pol- icy. When you enable revertManualSecurityGroupChanges , Firewall Manager identifies and reports when the security groups created by this policy become non-compliant. Fire- wall Manager won't distribute system tags added by Amazon Web Services services into the replica security groups. System tags begin with the aws: prefix. o Example: Shared VPCs. Apply the preceding policy to re- sources in shared VPCs as well as to those in VPCs that the account owns "{\"type\":\"SECURITY_GROUPS_COMMON\",\"re- vertManualSecurityGroupChanges\":false,\"exclusiveRe- sourceSecurityGroupManagement\":false, \"applyToAllEC2In- stanceENIs\":false,\"includeSharedVPC\":true,\"security- Groups\":[{\"id\":\" sg-000e55995d61a06bd\"}]}" o Example: SECURITY_GROUPS_CONTENT_AUDIT "{\"type\":\"SE- CURITY_GROUPS_CONTENT_AUDIT\",\"preManagedOp- tions\":[{\"denyProtocolAllValue\":true},{\"auditSgDirec- tion\":{\"type\":\"ALL\"}}],\"security- Groups\":[{\"id\":\"sg-049b2393a25468971\"}],\"security- GroupAction\":{\"type\":\"ALLOW\"}}" The security group action for content audit can be ALLOW or DENY . For ALLOW , all in-scope security group rules must be within the al- lowed range of the policy's security group rules. For DENY , all in-scope security group rules must not contain a value or a range that matches a rule value or range in the policy security group. o Example: SECURITY_GROUPS_USAGE_AUDIT "{\"type\":\"SECU- RITY_GROUPS_USAGE_AUDIT\",\"deleteUnusedSecurity- Groups\":true,\"coalesceRedundantSecurity- Groups\":true,\"optionalDelayForUnusedInMinutes\":60}" o Example: SHIELD_ADVANCED with web ACL management "{\"type\":\"SHIELD_ADVANCED\",\"optimizeUnassociatedWe- bACL\":true}" If you set optimizeUnassociatedWebACL to true , Firewall Manager creates web ACLs in accounts within the policy scope if the web ACLs will be used by at least one resource. Firewall Manager creates web ACLs in the ac- counts within policy scope only if the web ACLs will be used by at least one resource. If at any time an account comes into policy scope, Firewall Manager automatically creates a web ACL in the account if at least one resource will use the web ACL. Upon enablement, Firewall Manager performs a one-time cleanup of unused web ACLs in your ac- count. The cleanup process can take several hours. If a re- source leaves policy scope after Firewall Manager creates a web ACL, Firewall Manager doesn't disassociate the resource from the web ACL. If you want Firewall Manager to clean up the web ACL, you must first manually disassociate the re- sources from the web ACL, and then enable the manage unused web ACLs option in your policy. If you set optimizeUnasso- ciatedWebACL to false , and Firewall Manager automatically creates an empty web ACL in each account that's within pol- icy scope. o Specification for SHIELD_ADVANCED for Amazon CloudFront distributions "{\"type\":\"SHIELD_ADVANCED\",\"automati- cResponseConfiguration\": {\"automaticResponseSta- tus\":\"ENABLED|IGNORED|DISABLED\", \"automaticResponseAc- tion\":\"BLOCK|COUNT\"}, \"overrideCustomerWebaclClas- sic\":true|false, \"optimizeUnassociatedWe- bACL\":true|false}" For example: "{\"type\":\"SHIELD_AD- VANCED\",\"automaticResponseConfiguration\": {\"automati- cResponseStatus\":\"ENABLED\", \"automaticResponseAc- tion\":\"COUNT\"}}" The default value for automaticRe- sponseStatus is IGNORED . The value for automaticRespon- seAction is only required when automaticResponseStatus is set to ENABLED . The default value for overrideCustomerWe- baclClassic is false . For other resource types that you can protect with a Shield Advanced policy, this ManagedSer- viceData configuration is an empty string. o Example: THIRD_PARTY_FIREWALL Replace THIRD_PARTY_FIRE- WALL_NAME with the name of the third-party firewall. "{ "type":"THIRD_PARTY_FIREWALL", "thirdPartyFire- wall":"THIRD_PARTY_FIREWALL_NAME", "thirdPartyFirewallCon- fig":{ "thirdPartyFirewallPolicyList":["global-1"] }, "firewallDeploymentModel":{ "distributedFirewallDeployment- Model":{ "distributedFirewallOrchestrationConfig":{ "fire- wallCreationConfig":{ "endpointLocation":{ "availability- ZoneConfigList":[ { "availabilityZoneName":"${Availability- Zone}" } ] } }, "allowedIPV4CidrList":[ ] } } } }" o Example: WAFV2 - Account takeover prevention, Bot Control managed rule groups, optimize unassociated web ACL, and rule action override "{\"type\":\"WAFV2\",\"preProcess- RuleGroups\":[{\"ruleGroupArn\":null,\"overrideAc- tion\":{\"type\":\"NONE\"},\"managedRuleGroupIdenti- fier\":{\"versionEnabled\":null,\"version\":null,\"vendor- Name\":\"AWS\",\"managedRuleGroupName\":\"AWSManagedRule- sATPRuleSet\",\"managedRuleGroupConfigs\":[{\"awsmanage- dRulesATPRuleSet\":{\"loginPath\":\"/loginpath\",\"re- questInspection\":{\"payloadType\":\"FORM_EN- CODED|JSON\",\"usernameField\":{\"identi- fier\":\"/form/username\"},\"passwordField\":{\"identi- fier\":\"/form/password\"}}}}]},\"ruleGroupType\":\"Manage- dRuleGroup\",\"excludeRules\":[],\"sampledRequestsEn- abled\":true},{\"ruleGroupArn\":null,\"overrideAc- tion\":{\"type\":\"NONE\"},\"managedRuleGroupIdenti- fier\":{\"versionEnabled\":null,\"version\":null,\"vendor- Name\":\"AWS\",\"managedRuleGroupName\":\"AWSManagedRules- BotControlRuleSet\",\"managedRuleGroupConfigs\":[{\"awsman- agedRulesBotControlRuleSet\":{\"inspectionLevel\":\"TAR- GETED|COMMON\"}}]},\"ruleGroupType\":\"ManagedRule- Group\",\"excludeRules\":[],\"sampledRequestsEn- abled\":true,\"ruleActionOver- rides\":[{\"name\":\"Rule1\",\"actionToUse\":{\"al- low|block|count|captcha|chal- lenge\":{}}},{\"name\":\"Rule2\",\"actionToUse\":{\"al- low|block|count|captcha|challenge\":{}}}]}],\"postProcess- RuleGroups\":[],\"defaultAction\":{\"type\":\"AL- LOW\"},\"customRequestHandling\":null,\"customRe- sponse\":null,\"overrideCustomerWebACLAssocia- tion\":false,\"loggingConfiguration\":null,\"sample- dRequestsEnabledForDefaultActions\":true,\"optimizeUnasso- ciatedWebACL\":true}" o Bot Control - For information about AWSManagedRulesBot- ControlRuleSet managed rule groups, see AWSManagedRulesBotControlRuleSet in the WAF API Reference . o Fraud Control account takeover prevention (ATP) - For in- formation about the properties available for AWSManage- dRulesATPRuleSet managed rule groups, see AWSManagedRulesATPRuleSet in the WAF API Reference . o Optimize unassociated web ACL - If you set optimizeUnas- sociatedWebACL to true , Firewall Manager creates web ACLs in accounts within the policy scope if the web ACLs will be used by at least one resource. Firewall Manager creates web ACLs in the accounts within policy scope only if the web ACLs will be used by at least one resource. If at any time an account comes into policy scope, Firewall Manager automatically creates a web ACL in the account if at least one resource will use the web ACL. Upon enable- ment, Firewall Manager performs a one-time cleanup of un- used web ACLs in your account. The cleanup process can take several hours. If a resource leaves policy scope af- ter Firewall Manager creates a web ACL, Firewall Manager disassociates the resource from the web ACL, but won't clean up the unused web ACL. Firewall Manager only cleans up unused web ACLs when you first enable management of unused web ACLs in a policy. If you set optimizeUnassoci- atedWebACL to false Firewall Manager doesn't manage un- used web ACLs, and Firewall Manager automatically creates an empty web ACL in each account that's within policy scope. o Rule action overrides - Firewall Manager supports rule action overrides only for managed rule groups. To config- ure a RuleActionOverrides add the Name of the rule to override, and ActionToUse , which is the new action to use for the rule. For information about using rule action override, see RuleActionOverride in the WAF API Reference . o Example: WAFV2 - CAPTCHA and Challenge configs "{\"type\":\"WAFV2\",\"preProcessRuleGroups\":[{\"rule- GroupArn\":null,\"overrideAc- tion\":{\"type\":\"NONE\"},\"managedRuleGroupIdenti- fier\":{\"versionEnabled\":null,\"version\":null,\"vendor- Name\":\"AWS\",\"managedRuleGroupName\":\"AWSManagedRule- sAdminProtectionRuleSet\"},\"ruleGroupType\":\"ManagedRule- Group\",\"excludeRules\":[],\"sampledRequestsEn- abled\":true}],\"postProcessRuleGroups\":[],\"defaultAc- tion\":{\"type\":\"ALLOW\"},\"customRe- questHandling\":null,\"customResponse\":null,\"overrideCus- tomerWebACLAssociation\":false,\"loggingConfigura- tion\":null,\"sampledRequestsEnabledForDefaultAc- tions\":true,\"captchaConfig\":{\"immunityTimeProp- erty\":{\"immunityTime\":500}},\"challengeConfig\":{\"immu- nityTimeProperty\":{\"immunityTime\":800}},\"tokenDo- mains\":[\"google.com\",\"amazon.com\"],\"associationCon- fig\":{\"requestBody\":{\"CLOUDFRONT\":{\"defaultSizeIn- spectionLimit\":\"KB_16\"}}}}" o CAPTCHA and Challenge configs - If you update the pol- icy's values for associationConfig , captchaConfig , challengeConfig , or tokenDomains , Firewall Manager will overwrite your local web ACLs to contain the new value(s). However, if you don't update the policy's asso- ciationConfig , captchaConfig , challengeConfig , or tok- enDomains values, the values in your local web ACLs will remain unchanged. For information about association con- figs, see AssociationConfig . For information about CAPTCHA and Challenge configs, see CaptchaConfig and ChallengeConfig in the WAF API Reference . o defaultSizeInspectionLimit - Specifies the maximum size of the web request body component that an associated Ama- zon CloudFront distribution should send to WAF for in- spection. For more information, see DefaultSizeInspectionLimit in the WAF API Reference . o Example: WAFV2 - Firewall Manager support for WAF managed rule group versioning "{\"preProcessRule- Groups\":[{\"ruleGroupType\":\"ManagedRuleGroup\",\"over- rideAction\":{\"type\":\"NONE\"},\"sampledRequestsEn- abled\":true,\"managedRuleGroupIdentifier\":{\"managedRule- GroupName\":\"AWSManagedRulesAdminProtectionRule- Set\",\"vendorName\":\"AWS\",\"managedRuleGroupCon- figs\":null}}],\"postProcessRuleGroups\":[],\"defaultAc- tion\":{\"type\":\"ALLOW\"},\"customRe- questHandling\":null,\"tokenDomains\":null,\"customRe- sponse\":null,\"type\":\"WAFV2\",\"overrideCustomerWebA- CLAssociation\":false,\"sampledRequestsEnabledForDefaultAc- tions\":true,\"optimizeUnassociatedWebACL\":true,\"webA- CLSource\":\"RETROFIT_EXISTING\"}" To use a specific ver- sion of a WAF managed rule group in your Firewall Manager policy, you must set versionEnabled to true , and set ver- sion to the version you'd like to use. If you don't set versionEnabled to true , or if you omit versionEnabled , then Firewall Manager uses the default version of the WAF managed rule group. o Example: WAFV2 - Logging configurations "{\"type\":\"WAFV2\",\"preProcessRuleGroups\":[{\"rule- GroupArn\":null, \"overrideAc- tion\":{\"type\":\"NONE\"},\"managedRuleGroupIdentifier\": {\"versionEnabled\":null,\"version\":null,\"vendor- Name\":\"AWS\", \"managedRuleGroupName\":\"AWSManagedRule- sAdminProtectionRuleSet\"} ,\"ruleGroupType\":\"Manage- dRuleGroup\",\"excludeRules\":[], \"sampledRequestsEn- abled\":true}],\"postProcessRuleGroups\":[], \"defaultAc- tion\":{\"type\":\"ALLOW\"},\"customRequestHandling\" :null,\"customResponse\":null,\"overrideCustomerWebACLAsso- ciation\" :false,\"loggingConfiguration\":{\"logDestina- tionConfigs\": [\"arn:aws:s3:::aws-waf-logs-exam- ple-bucket\"] ,\"redactedFields\":[],\"loggingFilterCon- figs\":{\"defaultBehavior\":\"KEEP\", \"filters\":[{\"be- havior\":\"KEEP\",\"requirement\":\"MEETS_ALL\", \"condi- tions\":[{\"actionCondition\":\"CAPTCHA\"},{\"actionCondi- tion\": \"CHALLENGE\"}, {\"actionCondition\":\"EX- CLUDED_AS_COUNT\"}]}]}},\"sampledRequestsEnabledForDefault- Actions\":true}" Firewall Manager supports Amazon Kinesis Data Firehose and Amazon S3 as the logDestinationConfigs in your loggingConfiguration . For information about WAF log- ging configurations, see LoggingConfiguration in the WAF API Reference In the loggingConfiguration , you can spec- ify one logDestinationConfigs . Optionally provide as many as 20 redactedFields . The RedactedFieldType must be one of URI , QUERY_STRING , HEADER , or METHOD . o Example: WAF Classic "{\"rule- Groups\":[{\"id\":\"78cb36c0-1b5e-4d7d-82b2-cf48d3ad9659\",\"over- rideAction\":{\"type\":\"NONE\"}}],\"overrideCustomerWebA- CLAssociation\":true,\"defaultAction\":{\"type\":\"AL- LOW\"},\"type\":\"WAF\"}" Constraints: o min: 1 o max: 30000 o pattern: ^((?!\\[nr]).)+ PolicyOption -&gt; (structure) Contains the settings to configure a network ACL policy, a Network Firewall firewall policy deployment model, or a third-party firewall policy. NetworkFirewallPolicy -&gt; (structure) Defines the deployment model to use for the firewall pol- icy. FirewallDeploymentModel -&gt; (string) Defines the deployment model to use for the firewall policy. To use a distributed model, set PolicyOption to NULL . Possible values: o CENTRALIZED o DISTRIBUTED ThirdPartyFirewallPolicy -&gt; (structure) Defines the policy options for a third-party firewall policy. FirewallDeploymentModel -&gt; (string) Defines the deployment model to use for the third-party firewall policy. Possible values: o CENTRALIZED o DISTRIBUTED NetworkAclCommonPolicy -&gt; (structure) Defines a Firewall Manager network ACL policy. NetworkAclEntrySet -&gt; (structure) [required] The definition of the first and last rules for the network ACL policy. FirstEntries -&gt; (list) The rules that you want to run first in the Fire- wall Manager managed network ACLs. NOTE: Provide these in the order in which you want them to run. Firewall Manager will assign the specific rule numbers for you, in the network ACLs that it creates. You must specify at least one first entry or one last entry in any network ACL policy. (structure) Describes a rule in a network ACL. Each network ACL has a set of numbered ingress rules and a separate set of numbered egress rules. When determining whether a packet should be allowed in or out of a subnet associated with the network ACL, Amazon Web Services processes the entries in the network ACL ac- cording to the rule numbers, in ascending or- der. When you manage an individual network ACL, you explicitly specify the rule numbers. When you specify the network ACL rules in a Firewall Manager policy, you provide the rules to run first, in the order that you want them to run, and the rules to run last, in the order that you want them to run. Firewall Manager assigns the rule numbers for you when you save the net- work ACL policy specification. IcmpTypeCode -&gt; (structure) ICMP protocol: The ICMP type and code. Code -&gt; (integer) ICMP code. Constraints: o min: -2147483648 o max: 2147483647 Type -&gt; (integer) ICMP type. Constraints: o min: -2147483648 o max: 2147483647 Protocol -&gt; (string) [required] The protocol number. A value of "-1" means all protocols. Constraints: o min: 0 o max: 1024 PortRange -&gt; (structure) TCP or UDP protocols: The range of ports the rule applies to. From -&gt; (integer) The beginning port number of the range. Constraints: o min: 0 o max: 65535 To -&gt; (integer) The ending port number of the range. Constraints: o min: 0 o max: 65535 CidrBlock -&gt; (string) The IPv4 network range to allow or deny, in CIDR notation. Constraints: o min: 1 o max: 1024 Ipv6CidrBlock -&gt; (string) The IPv6 network range to allow or deny, in CIDR notation. Constraints: o min: 1 o max: 1024 RuleAction -&gt; (string) [required] Indicates whether to allow or deny the traffic that matches the rule. Possible values: o allow o deny Egress -&gt; (boolean) [required] Indicates whether the rule is an egress, or outbound, rule (applied to traffic leaving the subnet). If it's not an egress rule, then it's an ingress, or inbound, rule. ForceRemediateForFirstEntries -&gt; (boolean) [required] Applies only when remediation is enabled for the policy as a whole. Firewall Manager uses this set- ting when it finds policy violations that involve conflicts between the custom entries and the pol- icy entries. If forced remediation is disabled, Firewall Man- ager marks the network ACL as noncompliant and does not try to remediate. For more information about the remediation behavior, see Remediation for managed network ACLs in the Firewall Manager Developer Guide . LastEntries -&gt; (list) The rules that you want to run last in the Fire- wall Manager managed network ACLs. NOTE: Provide these in the order in which you want them to run. Firewall Manager will assign the specific rule numbers for you, in the network ACLs that it creates. You must specify at least one first entry or one last entry in any network ACL policy. (structure) Describes a rule in a network ACL. Each network ACL has a set of numbered ingress rules and a separate set of numbered egress rules. When determining whether a packet should be allowed in or out of a subnet associated with the network ACL, Amazon Web Services processes the entries in the network ACL ac- cording to the rule numbers, in ascending or- der. When you manage an individual network ACL, you explicitly specify the rule numbers. When you specify the network ACL rules in a Firewall Manager policy, you provide the rules to run first, in the order that you want them to run, and the rules to run last, in the order that you want them to run. Firewall Manager assigns the rule numbers for you when you save the net- work ACL policy specification. IcmpTypeCode -&gt; (structure) ICMP protocol: The ICMP type and code. Code -&gt; (integer) ICMP code. Constraints: o min: -2147483648 o max: 2147483647 Type -&gt; (integer) ICMP type. Constraints: o min: -2147483648 o max: 2147483647 Protocol -&gt; (string) [required] The protocol number. A value of "-1" means all protocols. Constraints: o min: 0 o max: 1024 PortRange -&gt; (structure) TCP or UDP protocols: The range of ports the rule applies to. From -&gt; (integer) The beginning port number of the range. Constraints: o min: 0 o max: 65535 To -&gt; (integer) The ending port number of the range. Constraints: o min: 0 o max: 65535 CidrBlock -&gt; (string) The IPv4 network range to allow or deny, in CIDR notation. Constraints: o min: 1 o max: 1024 Ipv6CidrBlock -&gt; (string) The IPv6 network range to allow or deny, in CIDR notation. Constraints: o min: 1 o max: 1024 RuleAction -&gt; (string) [required] Indicates whether to allow or deny the traffic that matches the rule. Possible values: o allow o deny Egress -&gt; (boolean) [required] Indicates whether the rule is an egress, or outbound, rule (applied to traffic leaving the subnet). If it's not an egress rule, then it's an ingress, or inbound, rule. ForceRemediateForLastEntries -&gt; (boolean) [required] Applies only when remediation is enabled for the policy as a whole. Firewall Manager uses this set- ting when it finds policy violations that involve conflicts between the custom entries and the pol- icy entries. If forced remediation is disabled, Firewall Man- ager marks the network ACL as noncompliant and does not try to remediate. For more information about the remediation behavior, see Remediation for managed network ACLs in the Firewall Manager Developer Guide . ResourceType -&gt; (string) [required] The type of resource protected by or in scope of the policy. This is in the format shown in the Amazon Web Services Resource Types Reference . To apply this policy to multiple resource types, specify a resource type of ResourceTypeList and then specify the resource types in a ResourceTypeList . The following are valid resource types for each Firewall Manager policy type: o Amazon Web Services WAF Classic - AWS::ApiGateway::Stage , AWS::CloudFront::Distribution , and AWS::ElasticLoadBalanc- ingV2::LoadBalancer . o WAF - AWS::ApiGateway::Stage , AWS::ElasticLoadBalanc- ingV2::LoadBalancer , and AWS::CloudFront::Distribution . o Shield Advanced - AWS::ElasticLoadBalancingV2::LoadBalancer , AWS::ElasticLoadBalancing::LoadBalancer , AWS::EC2::EIP , and AWS::CloudFront::Distribution . o Network ACL - AWS::EC2::Subnet . o Security group usage audit - AWS::EC2::SecurityGroup . o Security group content audit - AWS::EC2::SecurityGroup , AWS::EC2::NetworkInterface , and AWS::EC2::Instance . o DNS Firewall, Network Firewall, and third-party firewall - AWS::EC2::VPC . Constraints: o min: 1 o max: 128 o pattern: ^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$ ResourceTypeList -&gt; (list) An array of ResourceType objects. Use this only to specify mul- tiple resource types. To specify a single resource type, use Re- sourceType . (string) Constraints: o min: 1 o max: 128 o pattern: ^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$ ResourceTags -&gt; (list) An array of ResourceTag objects. Constraints: o min: 0 o max: 50 (structure) The resource tags that Firewall Manager uses to determine if a particular resource should be included or excluded from the Firewall Manager policy. Tags enable you to categorize your Amazon Web Services resources in different ways, for example, by purpose, owner, or environment. Each tag consists of a key and an optional value. If you add more than one tag to a pol- icy, you can specify whether to combine them using the logi- cal AND operator or the logical OR operator. For more infor- mation, see Working with Tag Editor . Every resource tag must have a string value, either a non-empty string or an empty string. If you don't provide a value for a resource tag, Firewall Manager saves the value as an empty string: "". When Firewall Manager compares tags, it only matches two tags if they have the same key and the same value. A tag with an empty string value only matches with tags that also have an empty string value. Key -&gt; (string) [required] The resource tag key. Constraints: o min: 1 o max: 128 o pattern: ^([\p{L}\p{Z}\p{N}_.:\/=+\-@*\\]*)$ Value -&gt; (string) The resource tag value. To specify an empty string value, either don't provide this or specify it as "". Constraints: o max: 256 o pattern: ^([\p{L}\p{Z}\p{N}_.:\/=+\-@*\\]*)$ ExcludeResourceTags -&gt; (boolean) [required] If set to True , resources with the tags that are specified in the ResourceTag array are not in scope of the policy. If set to False , and the ResourceTag array is not null, only resources with the specified tags are in scope of the policy. RemediationEnabled -&gt; (boolean) [required] Indicates if the policy should be automatically applied to new resources. DeleteUnusedFMManagedResources -&gt; (boolean) Indicates whether Firewall Manager should automatically remove protections from resources that leave the policy scope and clean up resources that Firewall Manager is managing for accounts when those accounts leave policy scope. For example, Firewall Manager will disassociate a Firewall Manager managed web ACL from a pro- tected customer resource when the customer resource leaves pol- icy scope. By default, Firewall Manager doesn't remove protections or delete Firewall Manager managed resources. This option is not available for Shield Advanced or WAF Classic policies. IncludeMap -&gt; (map) Specifies the Amazon Web Services account IDs and Organizations organizational units (OUs) to include in the policy. Specifying an OU is the equivalent of specifying all accounts in the OU and in any of its child OUs, including any child OUs and accounts that are added at a later time. You can specify inclusions or exclusions, but not both. If you specify an IncludeMap , Firewall Manager applies the policy to all accounts specified by the IncludeMap , and does not evaluate any ExcludeMap specifications. If you do not specify an In- cludeMap , then Firewall Manager applies the policy to all ac- counts except for those specified by the ExcludeMap . You can specify account IDs, OUs, or a combination: o Specify account IDs by setting the key to ACCOUNT . For exam- ple, the following is a valid map: {ACCOUNT : [accountID1, ac- countID2]} . o Specify OUs by setting the key to ORG_UNIT . For example, the following is a valid map: {ORG_UNIT : [ouid111, ouid112]} . o Specify accounts and OUs together in a single map, separated with a comma. For example, the following is a valid map: {AC- COUNT : [accountID1, accountID2], ORG_UNIT : [ouid111, ouid112]} . key -&gt; (string) Possible values: o ACCOUNT o ORG_UNIT value -&gt; (list) (string) Constraints: o min: 1 o max: 1024 o pattern: ^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$ ExcludeMap -&gt; (map) Specifies the Amazon Web Services account IDs and Organizations organizational units (OUs) to exclude from the policy. Specify- ing an OU is the equivalent of specifying all accounts in the OU and in any of its child OUs, including any child OUs and ac- counts that are added at a later time. You can specify inclusions or exclusions, but not both. If you specify an IncludeMap , Firewall Manager applies the policy to all accounts specified by the IncludeMap , and does not evaluate any ExcludeMap specifications. If you do not specify an In- cludeMap , then Firewall Manager applies the policy to all ac- counts except for those specified by the ExcludeMap . You can specify account IDs, OUs, or a combination: o Specify account IDs by setting the key to ACCOUNT . For exam- ple, the following is a valid map: {ACCOUNT : [accountID1, ac- countID2]} . o Specify OUs by setting the key to ORG_UNIT . For example, the following is a valid map: {ORG_UNIT : [ouid111, ouid112]} . o Specify accounts and OUs together in a single map, separated with a comma. For example, the following is a valid map: {AC- COUNT : [accountID1, accountID2], ORG_UNIT : [ouid111, ouid112]} . key -&gt; (string) Possible values: o ACCOUNT o ORG_UNIT value -&gt; (list) (string) Constraints: o min: 1 o max: 1024 o pattern: ^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$ ResourceSetIds -&gt; (list) The unique identifiers of the resource sets used by the policy. (string) Constraints: o min: 22 o max: 22 o pattern: ^[a-z0-9A-Z]{22}$ PolicyDescription -&gt; (string) Your description of the Firewall Manager policy. Constraints: o max: 256 o pattern: ^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$ PolicyStatus -&gt; (string) Indicates whether the policy is in or out of an admin's policy or Region scope. o ACTIVE - The administrator can manage and delete the policy. o OUT_OF_ADMIN_SCOPE - The administrator can view the policy, but they can't edit or delete the policy. Existing policy pro- tections stay in place. Any new resources that come into scope of the policy won't be protected. Possible values: o ACTIVE o OUT_OF_ADMIN_SCOPE ResourceTagLogicalOperator -&gt; (string) Specifies whether to combine multiple resource tags with AND, so that a resource must have all tags to be included or excluded, or OR, so that a resource must have at least one tag. Default: AND Possible values: o AND o OR JSON Syntax: { "PolicyId": "string", "PolicyName": "string", "PolicyUpdateToken": "string", "SecurityServicePolicyData": { "Type": "WAF"|"WAFV2"|"SHIELD_ADVANCED"|"SECURITY_GROUPS_COMMON"|"SECURITY_GROUPS_CONTENT_AUDIT"|"SECURITY_GROUPS_USAGE_AUDIT"|"NETWORK_FIREWALL"|"DNS_FIREWALL"|"THIRD_PARTY_FIREWALL"|"IMPORT_NETWORK_FIREWALL"|"NETWORK_ACL_COMMON", "ManagedServiceData": "string", "PolicyOption": { "NetworkFirewallPolicy": { "FirewallDeploymentModel": "CENTRALIZED"|"DISTRIBUTED" }, "ThirdPartyFirewallPolicy": { "FirewallDeploymentModel": "CENTRALIZED"|"DISTRIBUTED" }, "NetworkAclCommonPolicy": { "NetworkAclEntrySet": { "FirstEntries": [ { "IcmpTypeCode": { "Code": integer, "Type": integer }, "Protocol": "string", "PortRange": { "From": integer, "To": integer }, "CidrBlock": "string", "Ipv6CidrBlock": "string", "RuleAction": "allow"|"deny", "Egress": true|false } ... ], "ForceRemediateForFirstEntries": true|false, "LastEntries": [ { "IcmpTypeCode": { "Code": integer, "Type": integer }, "Protocol": "string", "PortRange": { "From": integer, "To": integer }, "CidrBlock": "string", "Ipv6CidrBlock": "string", "RuleAction": "allow"|"deny", "Egress": true|false } ... ], "ForceRemediateForLastEntries": true|false } } } }, "ResourceType": "string", "ResourceTypeList": ["string", ...], "ResourceTags": [ { "Key": "string", "Value": "string" } ... ], "ExcludeResourceTags": true|false, "RemediationEnabled": true|false, "DeleteUnusedFMManagedResources": true|false, "IncludeMap": {"ACCOUNT"|"ORG_UNIT": ["string", ...] ...}, "ExcludeMap": {"ACCOUNT"|"ORG_UNIT": ["string", ...] ...}, "ResourceSetIds": ["string", ...], "PolicyDescription": "string", "PolicyStatus": "ACTIVE"|"OUT_OF_ADMIN_SCOPE", "ResourceTagLogicalOperator": "AND"|"OR" }
    /// </summary>
    [CliOption("--policy")]
    public string? Policy { get; private init; }

    /// <summary>
    /// The tags to add to the Amazon Web Services resource. Constraints: o min: 0 o max: 200 (structure) A collection of key:value pairs associated with an Amazon Web Services resource. The key:value pair can be anything you de- fine. Typically, the tag key represents a category (such as "en- vironment") and the tag value represents a specific value within that category (such as "test," "development," or "production"). You can add up to 50 tags to each Amazon Web Services resource. Key -&gt; (string) [required] Part of the key:value pair that defines a tag. You can use a tag key to describe a category of information, such as "cus- tomer." Tag keys are case-sensitive. Constraints: o min: 1 o max: 128 o pattern: ^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$ Value -&gt; (string) [required] Part of the key:value pair that defines a tag. You can use a tag value to describe a specific value within a category, such as "companyA" or "companyB." Tag values are case-sensi- tive. Constraints: o min: 0 o max: 256 o pattern: ^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$ Shorthand Syntax: Key=string,Value=string ... JSON Syntax: [ { "Key": "string", "Value": "string" } ... ]
    /// </summary>
    [CliOption("--tag-list", GroupValues = true)]
    public IEnumerable<string>? TagList { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

